function fn_ab__sf_get_available_hash_variants($hash){
$res=[];$separator=ABSF_HASH_SEPARATE;if ($count=substr_count($hash,$separator)) {
$t_hash=$hash;$last_element=true;for ($i=0; $i <= $count; $i++) {
if (strpos($t_hash,$separator) !== false) {
$a_hash=substr($t_hash,0,strrpos($t_hash,$separator));$b_hash=substr($t_hash,strrpos($t_hash,$separator) + 1);} else {
$a_hash='';$b_hash=$t_hash;}
if (fn_ab__sf_find_currency_hash($b_hash)) {
if ($last_element) {
$last_element=false;} else {
$res[]=(!empty($a_hash)?$a_hash.$separator:'').$b_hash;}} elseif (substr_count($b_hash,'-') > 1) {
list($filter_id)=explode('-',$b_hash);$variants=(array) explode('-',substr($b_hash,strpos($b_hash,'-') + 1));if ($last_element) {
unset($variants[count($variants) - 1]);$last_element=false;}
for ($j=count($variants); $j > 0; $j--) {
$res[]=(!empty($a_hash)?$a_hash.$separator:'').$filter_id.'-'.implode('-',array_slice($variants,0,$j));}} else {
if ($last_element) {
$last_element=false;}
if (!empty($a_hash)) {
$res[]=$a_hash;}}
$t_hash=$a_hash;}}
return $res;}
function fn_ab__sf_find_currency_hash($hash){
static $currencies;if (empty($currencies)) {
$currencies=['USD','EUR','GBP','RUB'];}
foreach ($currencies as $currency) {
if (strpos($hash,$currency) !== false) {
return true;}}
return false;}
function fn_ab__seo_filters_ab__as_other_objects(&$objects){
