return false;}
switch ($seo_pages_fixed) {
case 'fixed': $cond=db_quote('AND n.fixed=?s',ABSFConfigs::PAGE_STATE_FIXED);break;case 'unfixed': $cond=db_quote('AND n.fixed=?s',ABSFConfigs::PAGE_STATE_UNFIXED);break;default: $cond=db_quote('AND n.fixed != ?s',ABSFConfigs::PAGE_STATE_HIDDEN);}
