$sql=[];foreach ($seo_filters as $filter) {
list($fields,$join,$condition)=fn_get_products([
'cid'=>$filter['category_id'],
'features_hash'=>$filter['features_hash'],
'get_conditions'=>true,
'subcats'=>true,
]);$condition.=db_quote(' AND ?:categories.status IN (?a) AND products.status=?s',['A','H'],'A');$query="SELECT {$filter['sf_id']} AS sf_id FROM ?:products as products $join WHERE 1 $condition GROUP BY sf_id";$sql[]='('.$query.')';}
$items=array_merge($items,db_get_fields(implode(' UNION ',$sql)));}
$filtered=[];foreach ($items as $id) {
$filtered[$id]=$_seo_filters[$id];}
return $filtered;}
